    # Defesa no banco: toda referência (cartão, fatura, compra, categoria, conta, lançamento)
    # precisa pertencer ao mesmo dono da linha. Roda com o papel da aplicação, sob RLS:
    # linhas de outras pessoas são invisíveis, então a checagem falha.
    op.execute("""
        CREATE FUNCTION check_owner_refs() RETURNS trigger LANGUAGE plpgsql AS $$
        DECLARE
          i int := 0; col text; tbl text; ref uuid; ok boolean;
        BEGIN
          WHILE i < TG_NARGS LOOP
            col := TG_ARGV[i]; tbl := TG_ARGV[i + 1];
            EXECUTE format('SELECT ($1).%I', col) INTO ref USING NEW;
            IF ref IS NOT NULL THEN
              IF tbl = 'categories' THEN
                SELECT EXISTS (SELECT 1 FROM categories c WHERE c.id = ref
                               AND (c.user_id IS NULL OR c.user_id = NEW.user_id)) INTO ok;
              ELSE
                EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I WHERE id = $1 AND user_id = $2)', tbl)
                  INTO ok USING ref, NEW.user_id;
              END IF;
              IF NOT ok THEN
                RAISE EXCEPTION 'referencia pertence a outro usuario (%)', col USING ERRCODE = '42501';
              END IF;
            END IF;
            i := i + 2;
          END LOOP;
          RETURN NEW;
        END $$;
    """)
    for table, args in OWNER_REFS.items():
        op.execute(
            f"CREATE TRIGGER {table}_owner_refs BEFORE INSERT OR UPDATE ON {table} "
            f"FOR EACH ROW EXECUTE FUNCTION check_owner_refs({args})"
        )


